import{_ as s,a0 as a,w as l,s as m,ao as p,I as r,a1 as o,A as i,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse(`{"title":"设置iSCSI的发起程序（客户端）（三） | LCTT x X-CMD","titleTemplate":false,"description":"设置iSCSI的发起程序（客户端）（三） | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"设置iSCSI的发起程序（客户端）（三） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"设置iSCSI的发起程序（客户端）（三） | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141217 Centralized Secure Storage (iSCSI)-- 'Initiator Client' Setup on RHEL or CentOS or Fedora -Part III","title":"设置iSCSI的发起程序（客户端）（三）","tag":"201503","desc":""},"relativePath":"201503/20141217 Centralized Secure Storage (iSCSI)-- 'Initiator Client' Setup on RHEL or CentOS or Fedora -Part III.md","filePath":"[post].md"}`),d={name:"201503/20141217 Centralized Secure Storage (iSCSI)-- 'Initiator Client' Setup on RHEL or CentOS or Fedora -Part III.md"};function g(c,t,u,w,S,f){const n=a("Link");return l(),m("div",null,[t[15]||(t[15]=p('<h1 id="设置iscsi的发起程序-客户端-三" tabindex="-1">设置iSCSI的发起程序（客户端）（三） <a class="header-anchor" href="#设置iscsi的发起程序-客户端-三" aria-label="Permalink to “设置iSCSI的发起程序（客户端）（三）”">​</a></h1><p><strong>iSCSI</strong> 发起程序是一种用于同 iSCSI 目标器认证并访问服务器上共享的LUN的客户端。我们可以在本地挂载的硬盘上部署任何操作系统，只需要安装一个包来与目标器验证。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Client-Initiator-Setup.jpg" alt="Client Initiator Setup"></p><p><em>初始器客户端设置</em></p><h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><ul><li>可以处理本地挂载磁盘上的任意文件系统</li><li>在使用fdisk命令分区后不需要重启系统</li></ul><h3 id="前置阅读" tabindex="-1">前置阅读 <a class="header-anchor" href="#前置阅读" aria-label="Permalink to “前置阅读”">​</a></h3>',7)),r("ul",null,[r("li",null,[o(n,{href:"http://linux.cn/article-4971-1.html"},{default:i(()=>[...t[0]||(t[0]=[e("使用iSCSI Target创建集中式安全存储（一）",-1)])]),_:1})]),r("li",null,[o(n,{href:"http://linux.cn/article-4972-1.html"},{default:i(()=>[...t[1]||(t[1]=[e("在 iSCSI Target 服务器中使用LVM创建和设置LUN（二）",-1)])]),_:1})])]),t[16]||(t[16]=p(`<h4 id="我的客户端设置" tabindex="-1">我的客户端设置 <a class="header-anchor" href="#我的客户端设置" aria-label="Permalink to “我的客户端设置”">​</a></h4><ul><li>操作系统 – CentOS 6.5 (Final)</li><li>iSCSI 目标器 IP – 192.168.0.50</li><li>使用的端口 : TCP 3260</li></ul><p><strong>警告</strong>：永远不要在LUN还挂载在客户端（发起程序）时停止服务。</p><h3 id="客户端设置" tabindex="-1">客户端设置 <a class="header-anchor" href="#客户端设置" aria-label="Permalink to “客户端设置”">​</a></h3><p><strong>1.</strong> 在客户端，我们需要安装包‘<strong>iSCSI-initiator-utils</strong>’，用下面的命令搜索包。</p><pre><code># yum search iscsi
</code></pre><p><strong>示例输出</strong></p><pre><code>============================= N/S Matched: iscsi ================================
iscsi-initiator-utils.x86_64 : iSCSI daemon and utility programs
iscsi-initiator-utils-devel.x86_64 : Development files for iscsi-initiator-utils
</code></pre><p><strong>2.</strong> 找到了包，就用下面的yum命令安装初始化包。</p><pre><code># yum install iscsi-initiator-utils.x86_64
</code></pre><p><strong>3.</strong> 安装完毕后，我们需要发现<strong>目标器</strong>上的共享。客户端的命令有点难记，因此我们使用man找到需要运行的命令列表。</p><pre><code># man iscsiadm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/man-iscsiadm.jpg" alt="man iscsiadm"></p><p><em>man iscsiadm</em></p><p><strong>4.</strong> 按下<strong>SHIFT+G</strong> 进入man页的底部并且稍微向上滚动找到示例的登录命令。下面的发现命令中，需要用我们的<strong>服务器IP地址</strong>来替换。</p><pre><code># iscsiadm --mode discoverydb --type sendtargets --portal 192.168.0.200 --discover
</code></pre><p><strong>5.</strong> 这里我们从下面的命令输出中找到了iSCSI的限定名（iqn）。</p><pre><code>192.168.0.200:3260,1 iqn.2014-07.com.tecmint:tgt1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Discover-Target.jpg" alt="Discover Target"></p><p><em>发现服务器</em></p><p><strong>6.</strong> 要登录就用下面的命令来连接一台LUN到我们本地系统中，这会与服务器验证并允许我们登录LUN。</p><pre><code># iscsiadm --mode node --targetname iqn.2014-07.com.tecmint:tgt1 --portal 192.168.0.200:3260 --login
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Login-To-Target-Server.jpg" alt="Login To Target Server"></p><p><em>登录到服务器</em></p><p><strong>注意</strong>：登出使用登录命令并在命令的最后使用logout来替换。</p><pre><code># iscsiadm --mode node --targetname iqn.2014-07.com.tecmint:tgt1 --portal 192.168.0.200:3260 --logout
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Logout-from-Target-Server.jpg" alt="Logout from Target Server"></p><p><em>登出服务器</em></p><p><strong>7.</strong> 登录服务器后，使用下面的命令列出节点的记录行。</p><pre><code># iscsiadm --mode node
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/List-Node.jpg" alt="List Node"></p><p><em>列出节点</em></p><p><strong>8.</strong> 显示特定节点的所有数据</p><pre><code># iscsiadm --mode node --targetname iqn.2014-07.com.tecmint:tgt1 --portal 192.168.0.200:3260
</code></pre><p><strong>示例输出</strong></p><pre><code># BEGIN RECORD 6.2.0-873.10.el6
node.name = iqn.2014-07.com.tecmint:tgt1
node.tpgt = 1
node.startup = automatic
node.leading_login = No
iface.hwaddress = &lt;empty&gt;
iface.ipaddress = &lt;empty&gt;
iface.iscsi_ifacename = default
iface.net_ifacename = &lt;empty&gt;
iface.transport_name = tcp
iface.initiatorname = &lt;empty&gt;
iface.bootproto = &lt;empty&gt;
iface.subnet_mask = &lt;empty&gt;
iface.gateway = &lt;empty&gt;
iface.ipv6_autocfg = &lt;empty&gt;
iface.linklocal_autocfg = &lt;empty&gt;
....
</code></pre><p><strong>9.</strong> 接着列出使用的磁盘，fdisk会列出所有的登录认证过的磁盘。</p><pre><code># fdisk -l /dev/sda
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/List-Disks.jpg" alt="List Disks"></p><p>列出磁盘</p><p><strong>10.</strong> 运行fdisk命令来创建一个新的分区</p><pre><code># fdisk -cu /dev/sda
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Create-New-Partition.jpg" alt="Create New Partition"></p><p><em>创建新分区</em></p><p><strong>注意</strong>：在使用fdisk创建新分区之后，我们无需重启，就像使用我们本地的文件系统一样就行。因为这个将远程共享存储挂载到本地了。</p><p><strong>11.</strong> 格式化新创建的分区</p><pre><code># mkfs.ext4 /dev/sda1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Format-New-Partition.jpg" alt="Format New Partition"></p><p><em>格式化新分区</em></p><p><strong>12.</strong> 创建一个目录来挂载新创建的分区</p><pre><code># mkdir /mnt/iscsi_share
# mount /dev/sda1 /mnt/iscsi_share/
# ls -l /mnt/iscsi_share/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Mount-New-Partition.jpg" alt="Mount New Partition"></p><p><em>挂载新分区</em></p><p><strong>13.</strong> 列出挂载点</p><pre><code># df -Th
</code></pre><ul><li><strong>-T</strong> – 输出文件系统类型</li><li><strong>-h</strong> – 以易读的方式显示大小</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/List-New-Partition.jpg" alt="List New Partition"></p><p><em>列出新分区</em></p><p><strong>14.</strong> 如果需要永久挂载，使用fdtab文件</p><pre><code># vim /etc/fstab
</code></pre><p><strong>15.</strong>在fstab后追加下面行</p><pre><code>/dev/sda1  /mnt/iscsi_share/   ext4    defaults,_netdev   0 0
</code></pre><p><strong>注意：</strong> 在fdtab中使用_netdev，说明这是一个网络设备。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Auto-Mount-Partition.jpg" alt="Auto Mount Partition"></p><p><em>自动挂载分区</em></p><p><strong>16.</strong> 最后检查我们fstab文件是否有错误。</p><pre><code># mount -av
</code></pre><ul><li><strong>-a</strong> – 所有挂载点</li><li><strong>-v</strong> – 冗余模式</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Verify-fstab-Entries.jpg" alt="Verify fstab Entries"></p><p><em>验证fstab文件</em></p><p>我们已经成功完成了我们的客户端配置。现在让我们像本地磁盘一样使用它吧。</p><hr>`,72)),r("p",null,[t[3]||(t[3]=e("via: ",-1)),o(n,{href:"http://www.tecmint.com/iscsi-initiator-client-setup/"},{default:i(()=>[...t[2]||(t[2]=[e("http://www.tecmint.com/iscsi-initiator-client-setup/",-1)])]),_:1})]),r("p",null,[t[7]||(t[7]=e("作者：",-1)),o(n,{href:"http://www.tecmint.com/author/babinlonston/"},{default:i(()=>[...t[4]||(t[4]=[e("Babin Lonston",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:i(()=>[...t[5]||(t[5]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const h=s(d,[["render",g]]);export{I as __pageData,h as default};
